package com.insight.quantlife;
import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.util.*;
/** Sessions and append-only original messages. Compaction stores derived memory, never deletes history. */
final class ChatStore {
 static final String LEGACY="legacy-chat";
 static void create(SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS chat_sessions(id TEXT PRIMARY KEY,created INTEGER NOT NULL,payload TEXT NOT NULL)");db.execSQL("ALTER TABLE messages ADD COLUMN session TEXT NOT NULL DEFAULT 'legacy-chat'");db.execSQL("CREATE INDEX message_session ON messages(session,created)");try{save(db,new JSONObject().put("id",LEGACY).put("title","之前的对话").put("createdAt",System.currentTimeMillis()).put("revision",0));}catch(Exception e){throw new IllegalStateException(e);}}
 static JSONObject session(SQLiteDatabase db,String id)throws Exception{try(Cursor c=db.rawQuery("SELECT payload FROM chat_sessions WHERE id=?",new String[]{id})){if(!c.moveToFirst())throw new Exception("会话不存在，请重新选择");return new JSONObject(c.getString(0));}}
 static JSONObject save(SQLiteDatabase db,JSONObject s)throws Exception{ContentValues v=new ContentValues();v.put("id",s.getString("id"));v.put("created",s.getLong("createdAt"));v.put("payload",s.toString());if(db.insertWithOnConflict("chat_sessions",null,v,SQLiteDatabase.CONFLICT_REPLACE)<0)throw new Exception("会话保存失败");return s;}
 static String active(SQLiteDatabase db,Context ctx)throws Exception{String id=ctx.getSharedPreferences("chat-ui",0).getString("active",LEGACY);try{session(db,id);return id;}catch(Exception e){try(Cursor c=db.rawQuery("SELECT id FROM chat_sessions ORDER BY created DESC LIMIT 1",null)){if(c.moveToFirst())return c.getString(0);}JSONObject s=new JSONObject().put("id",UUID.randomUUID().toString()).put("title","新对话").put("createdAt",System.currentTimeMillis()).put("revision",0);save(db,s);return s.getString("id");}}
 static JSONArray sessions(SQLiteDatabase db)throws Exception{JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT s.payload,MAX(s.created,COALESCE(MAX(m.created),0)) AS latest FROM chat_sessions s LEFT JOIN messages m ON m.session=s.id GROUP BY s.id ORDER BY latest DESC,s.created DESC",null)){while(c.moveToNext()){JSONObject s=new JSONObject(c.getString(0));s.remove("memory");s.put("updatedAt",c.getLong(1));a.put(s);}}return a;}
 /** Literal title/message search. Does not select a session or send content to a model. */
 static JSONArray search(SQLiteDatabase db,String query)throws Exception{
  query=query.trim().toLowerCase(Locale.ROOT);if(query.length()>160)throw new Exception("搜索词最多160字");JSONArray all=sessions(db);if(query.isEmpty())return all;
  Map<String,String> matches=new HashMap<>();String pattern="%"+query.replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%";
  try(Cursor c=db.rawQuery("SELECT session,payload FROM messages WHERE payload LIKE ? ESCAPE '\\' ORDER BY created DESC",new String[]{pattern})){while(c.moveToNext()){String text=new JSONObject(c.getString(1)).optString("text"),lower=text.toLowerCase(Locale.ROOT);int at=lower.indexOf(query);if(at>=0&&!matches.containsKey(c.getString(0)))matches.put(c.getString(0),text.substring(Math.max(0,at-16),Math.min(text.length(),at+query.length()+45)).replaceAll("\\s+"," "));}}
  JSONArray result=new JSONArray();for(int i=0;i<all.length();i++){JSONObject s=all.getJSONObject(i);if(s.optString("title").toLowerCase(Locale.ROOT).contains(query)||matches.containsKey(s.getString("id"))){if(matches.containsKey(s.getString("id")))s.put("matchPreview",matches.get(s.getString("id")));result.put(s);}}return result;
 }
 static JSONArray messages(SQLiteDatabase db,String id)throws Exception{JSONArray a=new JSONArray();String sql="SELECT payload,session FROM messages"+(id==null?"":" WHERE session=?")+" ORDER BY created,rowid";try(Cursor c=db.rawQuery(sql,id==null?null:new String[]{id})){while(c.moveToNext()){JSONObject m=new JSONObject(c.getString(0));m.put("sessionId",c.getString(1));a.put(m);}}return a;}
 static JSONObject get(SQLiteDatabase db,Context ctx,String id)throws Exception{if(id==null||id.isEmpty())id=active(db,ctx);JSONObject s=session(db,id);ctx.getSharedPreferences("chat-ui",0).edit().putString("active",id).commit();return new JSONObject().put("session",s).put("messages",messages(db,id)).put("sessions",sessions(db));}
 static JSONObject newSession(SQLiteDatabase db,Context ctx)throws Exception{JSONObject s=new JSONObject().put("id",UUID.randomUUID().toString()).put("title","新对话").put("createdAt",System.currentTimeMillis()).put("revision",0);save(db,s);return get(db,ctx,s.getString("id"));}
 static void message(SQLiteDatabase db,Context ctx,JSONObject m)throws Exception{String sid=m.optString("sessionId",active(db,ctx)),role=m.getString("role");JSONObject s=session(db,sid);if(!role.matches("user|assistant")||m.getString("text").length()>100000||m.optString("contextText").length()>100000||m.getString("id").length()>160)throw new Exception("对话格式无效");try(Cursor c=db.rawQuery("SELECT session FROM messages WHERE id=?",new String[]{m.getString("id")})){if(c.moveToFirst()&&!c.getString(0).equals(sid))throw new Exception("不能覆盖其他会话的消息");}m.put("sessionId",sid);ContentValues v=new ContentValues();v.put("id",m.getString("id"));v.put("created",m.getLong("createdAt"));v.put("session",sid);v.put("payload",m.toString());if(db.insertWithOnConflict("messages",null,v,SQLiteDatabase.CONFLICT_REPLACE)<0)throw new Exception("消息保存失败");if(role.equals("user")&&(s.optString("title").equals("新对话")||s.optString("title").equals("之前的对话"))){s.put("title",m.getString("text").replaceAll("\\s+"," ").substring(0,Math.min(28,m.getString("text").replaceAll("\\s+"," ").length())));save(db,s);}}
 static JSONObject memory(SQLiteDatabase db,JSONObject p)throws Exception{db.beginTransaction();try{String id=p.getString("sessionId");JSONObject s=session(db,id);if(s.optLong("revision")!=p.getLong("expectedRevision"))throw new Exception("会话已变化，未覆盖新摘要");JSONObject mem=p.getJSONObject("memory");if(mem.toString().length()>200000||mem.getJSONObject("summary").toString().length()>10000)throw new Exception("会话记忆过大");JSONArray ids=mem.getJSONArray("coveredIds");Set<String> valid=new HashSet<>();JSONArray ms=messages(db,id);for(int i=0;i<ms.length();i++)valid.add(ms.getJSONObject(i).getString("id"));for(int i=0;i<ids.length();i++)if(!valid.contains(ids.getString(i)))throw new Exception("摘要包含其他会话或不存在的消息");s.put("memory",mem).put("revision",s.optLong("revision")+1);save(db,s);db.setTransactionSuccessful();return s;}finally{db.endTransaction();}}
 static JSONObject remove(SQLiteDatabase db,Context ctx,String id,boolean whole)throws Exception{session(db,id);db.beginTransaction();try{db.delete("messages","session=?",new String[]{id});if(whole)db.delete("chat_sessions","id=?",new String[]{id});else{JSONObject s=session(db,id);s.remove("memory");s.put("revision",s.optLong("revision")+1);save(db,s);}db.setTransactionSuccessful();}finally{db.endTransaction();}return get(db,ctx,whole?null:id);}
}
